import utilsfrom utils import loggerimport streamlit as stfrom svc import svc_backend as backendst.header("Create Monitor")import authuser_code = auth.ensure_logged_in(required_access_level='guest')# ===========================================================# STEP 01# ===========================================================st.subheader("Step 01: Monitor Configuration")monitor_type = st.selectbox('Select Monitor Type', ['api', 'website', 'domain', 'server', 'ssl', 'database'], index=0)if monitor_type == 'api':    sample = """curl --location 'https://watchtower.finanssure.com/api/v1' \    --header 'Authorization:Bearer XXXXX==' \    --header 'version: 1'    """    cc = st.columns(2)    query = cc[0].text_area('Request cURL', value=sample, height=150)    monitor_body = utils.parse_curl_command(query)    cc[1].write('Parsed cURL')    if 'error' in monitor_body:        cc[1].warning(f"Error: {monitor_body['error']}")    else:        cc[1].code(f"Method:\t {monitor_body.get('method')} \nURL:\t {monitor_body.get('url')}  \nHeaders: {monitor_body.get('headers')}  \nParams:\t {monitor_body.get('params')}  \nBody:\t {monitor_body.get('body')}", language='bash')elif monitor_type == 'website':    sample = 'https://watchtower.finanssure.com'    monitor_body = st.text_input('Website URL', value=sample, placeholder='Enter Website URL')elif monitor_type == 'domain':    sample = 'finanssure.com'    monitor_body = st.text_input('Domain Name', value=sample, placeholder='Enter Domain Name')elif monitor_type == 'server':    sample = '20.207.73.82:443'    monitor_body = st.text_input('Server Host & Port', value=sample, placeholder='Enter Server Host & Port')elif monitor_type == 'ssl':    sample = 'finanssure.com'    monitor_body = st.text_input('Domain Name', value=sample, placeholder='Enter Domain Name')elif monitor_type == 'database':    sample = 'postgresql://POSTGRES_USER:POSTGRES_PASSWORD@DB_HOST:DB_PORT'    monitor_body = st.text_input('Database Connection String', value=sample, placeholder='Enter Database Connection String')else:    raise ValueError('Invalid Monitor Type')if st.button('Test Monitor'):    if monitor_type == 'api' and 'error' in monitor_body:        st.warning('Invalid cURL')    elif monitor_type != 'api' and monitor_body in [None, '']:        st.warning('Invalid Monitor Body')    else:        result = backend.check_monitor(monitor_type, monitor_body)        st.write(result)# ===========================================================# STEP 02# ===========================================================st.subheader("Step 02: Save & Schedule")monitor_name = st.text_input('Monitor Name', placeholder='Enter Monitor Name')cc = st.columns(2)monitor_timeout = cc[0].number_input('Request Timeout (seconds)', value=5)monitor_interval = cc[1].number_input('Monitor Interval (minutes)', value=5)# Expectationif monitor_type == 'api':    test_response = st.radio('Test Response Codes', ['Response Codes - Success', 'Response Codes - Failure'], index=0, horizontal=True)    all_response_codes = [200, 201, 202, 204, 301, 302, 304, 400, 401, 403, 404, 500, 502, 503, 504]    if test_response == 'Response Codes - Success':        is_allow_list = True        default_response_codes = [200, 201, 202, 204]    else:        is_allow_list = False        default_response_codes = [400, 401, 403, 404, 500, 502, 503, 504]    selected_response_codes = st.multiselect('Response Codes', all_response_codes, default=default_response_codes)    monitor_expectation = {        'is_allow_list': is_allow_list,        'response_codes': selected_response_codes    }else:    monitor_expectation = Nonealerts = st.multiselect('Alerts', ['slack', 'email', 'telegram', 'webhook'])if st.button('Create Monitor', type='primary'):    if user_code == 'guest':        st.warning('Login required to create monitor')    elif (monitor_body == sample) or (monitor_type == 'api' and monitor_body.get('url') in ['https://watchtower.finanssure.com/api/v1', None, '']) or (monitor_type == 'website' and monitor_body in ['https://finanssure.com', None, '']):        st.warning('Can not submit the Sample OR Invalid Monitor Body')    else:        res = backend.create_monitor(monitor_type, monitor_name, monitor_body, monitor_timeout, monitor_interval * 60, monitor_expectation, alerts, user_code, st.session_state.get('org_code'))        st.json(res)